    Invalid records fail the batch; only content duplicates are skipped.
    """
    seen = set(fingerprints)
    accepted, duplicate_count = [], 0
    for rec in records:
        validate_knowledge_point(rec.get('knowledge_point'), kp_id, kp_uuid)
